52	{
53	  opt::Opt opt(argc, argv);
54	  size_t seed = opt.is<size_t>("--seed", 0);
55	  seed = do_nothing(seed);
56	#ifdef USE_SYSTEMATIC_TESTING
57	#  ifdef WIN32
58	//  TODO: Not currently supported by snmalloc
59	//  default_memory_provider().systematic_bump_ptr() += seed << 17;
60	#  endif
61	#endif
62	
63	  memory_alloc::run_test();
64	  memory_iterator::run_test();
65	  memory_swap_root::run_test();
66	  memory_merge::run_test();
67	  memory_gc::run_test();
68	  memory_subregion::run_test();
69	
70	  test_alloc_pool();
71	  test_dealloc();
72	
73	  return 0;
74	}
